/* Person-specific program history. Demo visits are frozen snapshots, like completed sessions. */
function seedProgramVisits(plan,p){
 return [1,2].map((number,index)=>{
  const target=Number((plan.load.start*(1+plan.load.increase/100)**index).toFixed(1));
  const targets=Object.fromEntries([0,90,180,270].map(a=>[a,target]));
  const record={id:`${plan.id}-visit-${number}`,personId:p.id,programId:plan.id,programName:plan.name,programSession:number,clinicianName:clinicians.find(c=>c.id===p.assigned).name,type:'strength',purpose:'training',positions:4,reps:3,weight:target,partial:false,fixture:true,date:index?'6 Nov':'3 Nov',completedAt:Date.UTC(2026,10,index?6:3,15,30),completed:12,total:12,values:exampleValues('strength',4),sessionSettings:{type:'strength',purpose:'training',positions:4,reps:3,weight:target,targets,programId:plan.id,programName:plan.name,programSession:number,programTotal:6,programLoad:{...plan.load},programSource:null}};
  record.repRecords=[0,90,180,270].flatMap((angle,i)=>[1,2,3].map(rep=>({angle,rep,seconds:6,value:Number((target*([.96,.9,1.02,.92][i]+index*.025+(rep-2)*.015)).toFixed(1)),method:'Example completed hold'})));
  return record;
 });
}
function personProgramUI(){state.personProgramUI??={};return state.personProgramUI[state.personId]??={id:null,angle:'all',expanded:null};}
function selectedPersonProgram(){const plans=memberPrograms(),ui=personProgramUI();return plans.find(p=>p.id===ui.id)||plans.find(p=>p.completed<p.total)||plans[0];}
function programVisits(plan){return [...(plan.exampleVisits||[]),...state.history.filter(r=>r.personId===state.personId&&r.programId===plan.id)].sort((a,b)=>a.completedAt-b.completedAt);}
function programRows(plan){
 const visits=programVisits(plan),rows=[];
 for(let n=1;n<=plan.total;n++){
  const records=visits.filter(r=>r.programSession===n);
  if(records.length)records.forEach(r=>rows.push({number:n,record:r,status:r.partial?'Ended early':'Completed',targets:r.sessionSettings?.targets||null}));
  if(!records.some(r=>!r.partial)){
   const future=n>plan.completed,load=programLoad(plan),value=load.kind==='assessment'?null:Number((load.start*(load.kind==='incremental'?(1+load.increase/100)**(n-1):1)).toFixed(1));
   rows.push({number:n,record:null,status:future?(n===plan.completed+1?'Next session':'Planned'):'Record unavailable',targets:future&&value!==null?Object.fromEntries(Array.from({length:plan.positions},(_,i)=>[i*360/plan.positions,value])):null});
  }
 }
 return rows;
}
function programTargetValue(row,angle='all'){
 const values=angle==='all'?Object.values(row.targets||{}):[row.targets?.[angle]];
 return values.length&&values.every(Number.isFinite)?mean(values):null;
}
function programResultValue(row,field='force',angle='all'){
 if(!row.record||row.record.partial)return null;
 const data=reportData(row.record);return angle==='all'?data[field]:data.directions.find(d=>d.angle===Number(angle))?.[field]??null;
}
function programValue(value,unit='kg'){return Number.isFinite(value)?`${value.toFixed(unit==='%'?0:1)} <small class="program-unit">${unit}</small>`:'<span class="muted">—</span>';}
function programForceLabel(type){return ['eccentric','isokinetic'].includes(type)?'Average force':'Average peak force';}
function programChart(plan,rows,angle){
 const complete=rows.filter(row=>row.record&&!row.record.partial),targets=Array.from({length:plan.total},(_,i)=>rows.find(row=>row.number===i+1&&row.record&&!row.record.partial)||rows.find(row=>row.number===i+1&&!row.record));
 const maximum=Math.max(5,Math.ceil(Math.max(...rows.map(row=>programTargetValue(row,angle)||0),...complete.map(row=>programResultValue(row,'force',angle)||0))/5)*5),x=n=>58+(n-1)*904/Math.max(1,plan.total-1),y=v=>166-v/maximum*132;
 function path(values){let connected=false;return values.map(({number,value})=>{if(!Number.isFinite(value)){connected=false;return '';}const cmd=connected?'L':'M';connected=true;return `${cmd}${x(number)} ${y(value)}`;}).join(' ');}
 const measured=targets.map(row=>({number:row.number,value:programResultValue(row,'force',angle)}));
 return `<div class="person-program-chart"><svg viewBox="0 0 1000 206" role="group" aria-label="Force across ${plan.total} program sessions. Dashed line is target; solid line is result. Kilograms.">${[0,.5,1].map(t=>`<line x1="58" y1="${y(maximum*t)}" x2="962" y2="${y(maximum*t)}" stroke="var(--line)"/><text x="44" y="${y(maximum*t)+4}" text-anchor="end">${maximum*t}</text>`).join('')}<text x="28" y="18">kg</text><path d="${path(targets.map(row=>({number:row.number,value:programTargetValue(row,angle)})))}" fill="none" stroke="var(--plot-reference)" stroke-width="2" stroke-dasharray="5 5"/><path d="${path(measured)}" fill="none" stroke="var(--ink)" stroke-width="2.5"/>${targets.map(row=>{const value=programTargetValue(row,angle);return `${value===null?'':`<circle cx="${x(row.number)}" cy="${y(value)}" r="4" fill="var(--surface)" stroke="var(--plot-reference)" stroke-width="1.5"/>`}<text x="${x(row.number)}" y="191" text-anchor="middle">${row.number}</text>`;}).join('')}${complete.map(row=>{const value=programResultValue(row,'force',angle);if(!Number.isFinite(value))return '';return `<g role="button" tabindex="0" data-action="program-visit-toggle" data-id="${row.record.id}" aria-label="Session ${row.number}, ${escapeHTML(sessionStamp(row.record))}, ${value.toFixed(1)} kilograms. Show details."><circle cx="${x(row.number)}" cy="${y(value)}" r="22" fill="transparent"/><circle cx="${x(row.number)}" cy="${y(value)}" r="5" fill="${personProgramUI().expanded===row.record.id?'var(--signal)':'var(--ink)'}" stroke="var(--surface)" stroke-width="2"/></g>`;}).join('')}</svg><div class="person-program-legend"><span><i></i>${programForceLabel(plan.type)}</span><span><i class="target"></i>Target · used / planned</span><span>Session number</span></div>${!complete.length?'<p class="program-chart-empty">Results appear after the first completed session.</p>':''}</div>`;
}
function programVisitDetails(record){
 const data=record.partial?null:reportData(record),angles=Object.keys(record.sessionSettings?.targets||{}).map(Number),note=sessionNote(record),source=record.sessionSettings?.programSource;
 return `<div class="program-visit-details"><header><div><h3>Session ${record.programSession} · ${sessionStamp(record)}</h3><p>${record.positions} directions · ${record.reps} reps per direction${record.partial?` · ${record.completed} of ${record.total} reps completed`:''}${record.clinicianName?' · '+escapeHTML(record.clinicianName):''}</p></div>${button('View report '+icon('chevron','icon-sm'),'program-visit-report','small-button',`data-id="${record.id}"`)}</header><div class="program-angle-scroll"><table class="data-table"><thead><tr><th>Direction</th><th>Target used</th><th>${programForceLabel(record.type)}</th>${record.type==='endurance'?'<th>Hold time</th>':''}<th>Stability</th></tr></thead><tbody>${angles.map(a=>{const d=data?.directions.find(d=>d.angle===a);return `<tr><th>${a}° · ${reportDirectionNames[a/45]}</th><td>${programValue(record.sessionSettings.targets[a])}</td><td>${programValue(d?.force)}</td>${record.type==='endurance'?`<td>${programValue(d?.duration,'s')}</td>`:''}<td>${programValue(d?.stability,'%')}</td></tr>`;}).join('')}</tbody></table></div><p class="program-snapshot-note">${source?'Based on strength assessment '+sessionStamp(source)+'. ':''}Targets saved with this session.${!angles.length?' Target values were not recorded.':''}</p>${note?.text?`<p class="program-visit-note"><strong>Session note</strong> ${escapeHTML(note.text)}</p>`:''}</div>`;
}
function personProgramsView(){
 const plans=memberPrograms(),plan=selectedPersonProgram(),ui=personProgramUI();
 if(!plan)return `<section class="person-programs program-no-plan"><h2>No programs yet</h2><p>Create a plan to track targets and results across sessions.</p>${button('New program','person-program-new','primary')}</section>`;
 ui.id=plan.id;const rows=programRows(plan),angles=[...new Set([...Array.from({length:plan.positions},(_,i)=>i*360/plan.positions),...rows.flatMap(r=>Object.keys(r.targets||{}).map(Number))])].sort((a,b)=>a-b);if(ui.angle!=='all'&&!angles.includes(Number(ui.angle)))ui.angle='all';
 const label=programForceLabel(plan.type);
 return `<section class="person-programs"><header class="person-program-heading"><div>${plans.length>1?`<label class="sr-only" for="person-program-select">Program</label><select id="person-program-select">${plans.map(p=>`<option value="${p.id}" ${p.id===plan.id?'selected':''}>${escapeHTML(p.name)}${p.completed>=p.total?' · Completed':''}</option>`).join('')}</select>`:`<h2>${escapeHTML(plan.name)}</h2>`}<p>${sessionModes[plan.type].name} · ${plan.completed} of ${plan.total} completed · ${programLoadLabel(plan)}</p></div><div class="button-row">${button('New program','person-program-new','small-button')}${plan.completed<plan.total?button('Continue · Session '+(plan.completed+1),'continue-program','primary small-button',`data-program-id="${plan.id}"`):'<span class="badge">Completed</span>'}</div></header><div class="program-completion" role="progressbar" aria-label="Program completion" aria-valuemin="0" aria-valuemax="${plan.total}" aria-valuenow="${plan.completed}"><span style="width:${Math.min(100,plan.completed/plan.total*100)}%"></span></div><div class="program-chart-heading"><h3>Target & result</h3><label>Direction <select id="person-program-angle"><option value="all" ${ui.angle==='all'?'selected':''}>All directions · average</option>${angles.map(a=>`<option value="${a}" ${Number(ui.angle)===a&&ui.angle!=='all'?'selected':''}>${a}° · ${reportDirectionNames[a/45]}</option>`).join('')}</select></label></div>${programChart(plan,rows,ui.angle)}<div class="program-table-heading"><h3>Sessions</h3><p>Completed targets are saved values. Future targets are planned.</p></div><div class="program-session-scroll"><table class="data-table program-session-table"><thead><tr><th>Session</th><th>Date & time</th><th>Target · kg</th><th>${label} · kg</th>${plan.type==='endurance'?'<th>Hold time · s</th>':''}<th>Stability</th><th>Status</th></tr></thead><tbody>${rows.map(row=>{const r=row.record,key=r?.id,expanded=key&&ui.expanded===key,target=programTargetValue(row,ui.angle);return `<tr class="${r?'program-visit-row':''} ${expanded?'is-expanded':''}" ${r?`data-action="program-visit-toggle" data-id="${key}"`:''}><th>${r?`<button type="button" aria-label="Session ${row.number}, ${sessionStamp(r)} details" aria-expanded="${!!expanded}" aria-controls="detail-${key}">${icon(expanded?'down':'chevron','icon-sm')} ${row.number}</button>`:row.number}</th><td>${r?`${sessionDate(r)}<small>${sessionTime(r)}</small>`:row.status==='Record unavailable'?'Not recorded':'—'}</td><td>${target===null?(row.status==='Record unavailable'?'Not recorded':programLoad(plan).kind==='assessment'&&!r?'Calculated at setup':'—'):programValue(target,'')}<small>${r?'Used':row.status==='Record unavailable'?'':'Planned'}</small></td><td>${programValue(programResultValue(row,'force',ui.angle),'')}</td>${plan.type==='endurance'?`<td>${programValue(programResultValue(row,'duration',ui.angle),'')}</td>`:''}<td>${programValue(programResultValue(row,'stability',ui.angle),'%')}</td><td><span class="program-status ${row.status==='Next session'?'next':''}">${row.status}</span>${r&&sessionNote(r)?.text?'<small>Note attached</small>':''}</td></tr>${r?`<tr id="detail-${key}" ${expanded?'':'hidden'}><td colspan="${plan.type==='endurance'?7:6}">${expanded?programVisitDetails(r):''}</td></tr>`:''}`;}).join('')}</tbody></table></div></section>`;
}
function refreshPersonProgram(focus){render();if(focus)$(focus)?.focus({preventScroll:true});}
const personProgramActions={
 'person-program-new':()=>{openSessionPicker();state.overlay.step='create-program';updatePicker('#program-name');},
 'program-visit-toggle':el=>{const ui=personProgramUI(),plan=selectedPersonProgram();if(!programVisits(plan).some(r=>r.id===el.dataset.id))return;ui.expanded=ui.expanded===el.dataset.id?null:el.dataset.id;refreshPersonProgram(`[data-action="program-visit-toggle"][data-id="${el.dataset.id}"] button`);if(ui.expanded)$("#detail-"+ui.expanded)?.scrollIntoView({block:"nearest"});},
 'program-visit-report':el=>{const r=programVisits(selectedPersonProgram()).find(r=>r.id===el.dataset.id);if(!r)return;state.result=r;state.stage='review';state.reportReturnTab='programs';state.showCompare=reportCanCompare(r);state.reportDetails=false;render();window.scrollTo(0,0);}
};
document.addEventListener('change',event=>{const el=event.target,ui=()=>personProgramUI();if(el.id==='person-program-select'){ui().id=el.value;ui().expanded=null;ui().angle='all';refreshPersonProgram('#person-program-select');}if(el.id==='person-program-angle'){ui().angle=el.value;refreshPersonProgram('#person-program-angle');}});
